public boolean validateWrite()
{
    boolean ret = next validateWrite();

    if (ret)
    {
        if (this.ModuleInventCustVend == ModuleInventCustVend::Vend && this.METInvoiceConsolidationByRebateType
            && !this.METVendAccount)
        {
            ret = checkFailed("Vend account is mandatory");
        }
    }

    return ret;
}

/// <summary>
/// Is vend module
/// </summary>
/// <returns></returns>
boolean met_isVendorRebate()
{
    return this.ModuleInventCustVend == ModuleInventCustVend::Vend;
}
